
/* V24 - logo do cabeçalho sem tarja preta */
function pdfHeaderLogoTransparent(src){
  return new Promise((resolve)=>{
    try{
      const img=new Image();
      img.onload=()=>{
        const c=document.createElement("canvas");
        c.width=img.naturalWidth||img.width;
        c.height=img.naturalHeight||img.height;
        const ctx=c.getContext("2d");
        ctx.drawImage(img,0,0);
        const d=ctx.getImageData(0,0,c.width,c.height);
        for(let i=0;i<d.data.length;i+=4){
          const r=d.data[i], g=d.data[i+1], b=d.data[i+2], mx=Math.max(r,g,b);
          if(mx<35) d.data[i+3]=0;
          else if(mx<60) d.data[i+3]=Math.round((mx-35)/25*255);
        }
        ctx.putImageData(d,0,0);
        resolve(c.toDataURL("image/png"));
      };
      img.onerror=()=>resolve(src);
      img.src=src;
    }catch(e){ resolve(src); }
  });
}

/* AUTO_UPDATE_V38 — atualização automática + aviso flutuante */
(function(){
  const BUILD_VERSION="46.0";
  const BUILD_KEY="impacto-pro-installed-version";
  const VERSION_URL="./version.json?v="+encodeURIComponent(BUILD_VERSION);
  let initialController=!!navigator.serviceWorker?.controller;
  let updateNoticeShown=false;
  let justReloadedForUpdate=false;
  try{ justReloadedForUpdate=sessionStorage.getItem("impacto-update-reloaded")==="1"; sessionStorage.removeItem("impacto-update-reloaded"); }catch(e){}

  function showUpdateNotice(message="Uma nova versão do Impacto Pro está disponível."){
    if(justReloadedForUpdate) return;
    if(updateNoticeShown || document.getElementById("impactoUpdateNotice")) return;
    updateNoticeShown=true;
    const el=document.createElement("div");
    el.id="impactoUpdateNotice";
    el.innerHTML='<div class="impacto-update-box"><div class="impacto-update-icon">↻</div><div class="impacto-update-copy"><strong>Impacto Pro foi atualizado</strong><p>'+message+'</p></div><button id="impactoUpdateReload" type="button">RECARREGAR</button></div>';
    document.body.appendChild(el);
    document.getElementById("impactoUpdateReload").onclick=()=>{ try{sessionStorage.setItem("impacto-update-reloaded","1");}catch(e){} location.reload(); };
  }

  async function checkVersion(){
    try{
      const r=await fetch(VERSION_URL,{cache:"no-store",headers:{"Cache-Control":"no-cache"}});
      if(!r.ok) return;
      const data=await r.json();
      const remote=String(data.version||"");
      const local=String(BUILD_VERSION);
      const previous=localStorage.getItem(BUILD_KEY);
      if(previous && previous!==local && remote===local){
        showUpdateNotice("As atualizações já foram baixadas. Recarregue o aplicativo para aplicá-las.");
      } else if(remote && remote!==local){
        showUpdateNotice("Uma nova versão está disponível. Recarregue o aplicativo para atualizar.");
        if(navigator.serviceWorker?.getRegistration){
          const reg=await navigator.serviceWorker.getRegistration("./");
          if(reg) reg.update().catch(()=>{});
        }
      }
      localStorage.setItem(BUILD_KEY,local);
    }catch(e){}
  }

  async function registerAndCheck(){
    if(!("serviceWorker" in navigator)) return;
    try{
      const reg=await navigator.serviceWorker.register("./sw.js?v="+encodeURIComponent(BUILD_VERSION),{updateViaCache:"none"});
      await reg.update();
      if(reg.waiting && initialController){
        showUpdateNotice("A atualização está pronta. Recarregue o aplicativo para usar a versão mais recente.");
      }
      navigator.serviceWorker.addEventListener("controllerchange",()=>{
        if(initialController) showUpdateNotice("A nova versão foi instalada. Recarregue o aplicativo para aplicar a atualização.");
        initialController=true;
      });
    }catch(e){}
    checkVersion();
  }

  window.addEventListener("load",()=>{
    setTimeout(registerAndCheck,150);
    setInterval(()=>{
      checkVersion();
      navigator.serviceWorker?.getRegistration?.("./").then(reg=>reg?.update?.()).catch(()=>{});
    },60000);
  });
})();

